/*
 * LD_PRELOAD shim: redirect hardcoded /tmp/check_* paths to $TMPDIR/check_*
 *
 * libcheck 0.15 creates its IPC temp file via fopen("/tmp/check_XXXXXX","r+")
 * with the path generated by mkstemp inside its open_tmp_file() function.
 * On hosts where /tmp is read-only this makes every forked test fail.
 *
 * We intercept fopen() here and rewrite any path that starts with /tmp/check
 * to use $TMPDIR instead.  Other fopen() calls are passed through unchanged.
 */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TMP_CKPREFIX "/tmp/check"

static const char *get_real_tmpdir(void)
{
    const char *t = getenv("TMPDIR");
    return (t && t[0]) ? t : "/tmp";
}

FILE *fopen(const char *path, const char *mode)
{
    static FILE *(*real_fopen)(const char *, const char *) = NULL;
    if (!real_fopen)
        real_fopen = dlsym(RTLD_NEXT, "fopen");

    if (strncmp(path, TMP_CKPREFIX, sizeof(TMP_CKPREFIX) - 1) == 0) {
        char buf[4096];
        snprintf(buf, sizeof(buf), "%s%s", get_real_tmpdir(),
                 path + 4 /* skip "/tmp" → keep "/check_XXXXXX" */);
        return real_fopen(buf, mode);
    }
    return real_fopen(path, mode);
}

FILE *fopen64(const char *path, const char *mode)
{
    return fopen(path, mode);
}
